abil_head = ParagraphStyle("ah", parent=cell, fontName="DVS-B", alignment=TA_CENTER, textColor=GREEN)
def on_page(c, doc):
    c.saveState(); c.setFont("DVS", 7.8); c.setFillColor(MUTED)
    c.drawString(doc.leftMargin, 0.42*inch, "Handsome Jack  ·  D&D 5th Edition build (2024 rules; the Artificer is Eberron: Forge of the Artificer; Expendable Assets is homebrew)")
    c.drawRightString(letter[0]-doc.rightMargin, 0.42*inch, f"page {doc.page}"); c.restoreState()
doc = SimpleDocTemplate("../pdf/Handsome_Jack_5e_Build.pdf", pagesize=letter, leftMargin=0.6*inch, rightMargin=0.6*inch, topMargin=0.6*inch, bottomMargin=0.7*inch, title="Handsome Jack — D&D 5e Build", author="Claude")
W = letter[0] - 1.2*inch; S = []

def hb(name, tag, text):
    return KeepTogether([P(name, hb_name), P(tag, hb_tag), P(text, small)])

S.append(P("Handsome Jack", title))
S.append(P("Human · Artificer (Artillerist) 20 · Merchant · President of the Hyperion Corporation and, by his own account, the hero of Pandora, on the day he opened the Vault of the Warrior", subtitle))
S.append(HRFlowable(width="100%", thickness=1.4, color=GREEN, spaceBefore=4, spaceAfter=8))
S.append(P("Built on the 2024 rules, with the Artificer from <i>Eberron: Forge of the Artificer</i> (2025), from the games in this order. <b>Borderlands 2</b> (2012), where he is the villain and the last fight but one. <b>Borderlands: The Pre-Sequel</b> (2014), which is how a Hyperion programmer called John got there, told by someone who worked for him. <b>Tales from the Borderlands</b> (2014–15) and <b>Borderlands 3</b> (2019), for what was left afterwards: an AI copy, and a body double who outlived him. The first game matters once: its Guardian Angel turns out to have been his."))
S.append(P("<b>Design calls.</b> He's a man. No Siren, no Eridian blood, no cybernetics worth the name: a programmer with a standard array, Strength 10, and 143 hit points at level 20. Everything he does in a fight is something he built, bought or stole the patent for, so he's an Artificer, and the fight at the Vault is two turrets and a surveyor that keeps putting his shield back, so he's an Artillerist. Intelligence is the stat. Charisma is 18 because half a planet believed the billboards, and Wisdom is 8 because he does too. No armor: a jacket, a waistcoat and a mask. One homebrew feature, <b>Expendable Assets</b>, for the digistructed copies of himself. What Hyperion does for him, the Loaders, the moonshots, the station, the doubles, is not on the sheet: this is the man, not the company."))

S.append(P("Snapshot: the Vault of the Warrior, level 20", h2)); S.append(rule())
block = [P("Handsome Jack", statname),
 P("Medium Humanoid (Human) · a jacket over a waistcoat over a yellow shirt, a mask of his own face clasped on over what the Vault left of it, a pocket watch · “I am the goddamn hero!” (<i>Borderlands 2</i>)", stattag),
 P("<b>AC</b> 15 (no armor: Bracers of Defense, a Ring and a Cloak of Protection), <b>17 within 10 ft of one of his cannons</b> (Half Cover), 22 with Shield · <b>HP</b> 143, under 2d8+5 temporary from the Protector · <b>Speed</b> 30 ft · <b>Initiative</b> +7 (Alert) · <b>Proficiency</b> +6 · <b>Spell attack</b> +11, <b>+13 through the wrist laser</b> · <b>Save DC</b> 19", stat),
 abil_table(["10 (+0)","12 (+1)","14 (+2)","21 (+5)","8 (−1)","18 (+4)"], W-24), Spacer(1,4),
 P("<b>Saves</b> Str +2, Dex +3 (+5 beside a cannon), Con +10, Int +13, Wis +1, Cha +6, the ring and the cloak included · <b>Skills</b> Arcana +11, Investigation +11, Deception +10, Persuasion +10, Animal Handling +5 (a pony made of diamonds) · <b>Tools</b> thieves', tinker's, smith's and navigator's · <b>Telepathic</b> (the ECHO): he speaks into any head within 60 ft, whether it called or not", stat),
 P("<b>Defenses.</b> Two <b>Digi-Jacks</b> stand beside him for the first minute: when an attack hits him, roll a d6 for each, and on a 4 or higher it hit that one. <b>Shield</b> on his 1st- to 3rd-level slots (Reaction, +5 AC until his next turn). <b>Flash of Genius</b>, five a day: Reaction, +5 to a save or check he just failed. <b>Lucky</b>, six points: Disadvantage on an attack against him, or Advantage on his own d20. <b>Boon of Fate</b>, once a fight: 2d4 off a roll that just beat him. <b>Soul of Artifice</b>: at 0 HP he disintegrates any number of the six items he built and stands at 20 HP for each. One at a time, that's six times.", stat),
 P("<b>Attacks.</b> <b>Wrist laser</b> (Fire Bolt through his Arcane Firearm): +13, 120 ft, 4d10 + 1d8 fire; Ray of Frost for 4d8 + 1d8 cold when fire won't do. <b>Scorching Ray</b> on a 4th- or 5th-level slot: five or six rays at +13, 2d6 fire each. <b>Fireball</b> for a crowd, 8d6 to 10d6, DC 19. <b>Two Eldritch Cannons</b> on one Bonus Action (AC 18, 100 HP each), each choosing a mode every time: Force Ballista, +11, 120 ft, 3d8 force and a 5-ft push; Flamethrower, 15-ft cone, 3d8 fire, Dex save for half; Protector, 2d8+5 temporary hit points to him. <b>Digi-Jacks</b>: at the end of his turn each fires once, +11, 1d10 fire. A Hyperion pistol in the jacket (+7, 1d10+1 piercing) that he has no reason to draw.", stat),
 P("<b>What he built</b> (Replicate Magic Item, six items, five attuned of a possible six). The wrist laser, a <b>Wand of the War Mage +2</b> and his Arcane Firearm. <b>Bracers of Defense</b>. A <b>Ring of Protection</b>. A <b>Cloak of Protection</b>, which is the jacket. A <b>Mind Sharpener</b> in the waistcoat: four charges, a Reaction to succeed on a failed concentration save. A <b>Bag of Holding</b>, which is a storage deck. <b>Spell-Storing Item</b>, in the laser: Invisibility, ten uses a day, an action each. That's the cloak.", stat),
 P("<b>Spells</b> (slots 4/3/3/3/2; one 1st-level slot goes into the second cannon). Cantrips: Fire Bolt, Ray of Frost, Message, Prestidigitation, Mending. Artillerist: Shield, Thunderwave, Scorching Ray, Shatter, Fireball, Wind Wall, Ice Storm, Wall of Fire, Cone of Cold, Wall of Force. Prepared: Cure Wounds, Detect Magic, Identify, Invisibility, Blur, See Invisibility, Heat Metal, Haste, Dispel Magic, Fly, Otiluke's Resilient Sphere, Summon Construct, Fabricate, Animate Objects, Bigby's Hand.", stat),
 P("<b>Feats</b> Lucky (Merchant), Alert (Human), +2 Int, Telepathic, +2 Cha twice, Boon of Fate · <b>Artificer 20</b> Tinker's Magic, Replicate Magic Item, Magic Item Tinker, Flash of Genius, Spell-Storing Item, Advanced Artifice, Magic Item Master, Soul of Artifice · <b>Artillerist</b> Eldritch Cannon, Arcane Firearm, Explosive Cannon, Fortified Position · <b>Expendable Assets</b> (homebrew, below)", stat),
 P("<b>How he fights.</b> From behind things, talking. The Digi-Jacks are up before anyone has moved and the cannons were set before anyone arrived. If the other side moved first, or is someone who shoots, he opens under the cloak and lets the cannons work; otherwise it's the laser from the first turn, the big slots as Scorching Ray until they're gone, and a cannon turned to Protector whenever his shield is down. He has no plan for anyone who reaches him, only more things to give up.", stat)]
box = Table([[f] for f in block], colWidths=[W]); box.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("BOX",(0,0),(-1,-1),1.0,GREEN),("LEFTPADDING",(0,0),(-1,-1),11),("RIGHTPADDING",(0,0),(-1,-1),11),("TOPPADDING",(0,0),(-1,-1),1),("BOTTOMPADDING",(0,0),(-1,-1),1),("TOPPADDING",(0,0),(-1,0),9),("BOTTOMPADDING",(0,-1),(-1,-1),9)])); S.append(box)

S.append(P("The kit: what the games show, and what rule it is", h2)); S.append(rule())
S.append(P("The last fight of <i>Borderlands 2</i>, at the Vault of the Warrior, is the whole list: he opens by splitting into copies of himself, he has a heavy shield, a personal surveyor that restores the shield until someone shoots it down, turrets, a cloak, and a wrist-mounted laser. Six things, and five of them are in the Artificer already.", small))
S.append(hb("Expendable Assets", "Homebrew · level 3 with one Digi-Jack, two from level 11 · once per Short or Long Rest, no action",
 "When he rolls Initiative, he can digistruct two <b>Digi-Jacks</b> in unoccupied spaces within 10 ft of him. They last 1 minute. They're hard light in his shape: they have no hit points and can't be targeted on their own. <b>Which Jack?</b> When an attack roll hits him, roll a d6 for each Digi-Jack standing. On a 4 or higher the attack hit that one instead: it's destroyed, and he takes nothing. With both up that's three hits in four. Saving throws and areas find the real one. <b>More where that came from.</b> At the start of each of his turns, if fewer than two are standing, one re-digistructs. <b>Covering fire.</b> At the end of each of his turns, each Digi-Jack makes one ranged spell attack with his modifier (+11) at a target he can see within 120 ft: 1d10 fire. The name is the Doppelganger's action skill in the Pre-Sequel. That Doppelganger is one of his body doubles, not him, and the skill is on this sheet because the original opens his own last fight the same way and because the patent is his."))
S.append(hb("The wrist laser", "Wand of the War Mage +2, carved as his Arcane Firearm · Fire Bolt",
 "A cantrip, so it never runs dry: +13 to hit, 4d10 fire, and the Arcane Firearm's 1d8 on one damage roll a turn. The wand's other property, ignoring Half Cover, matters to him more than to most: he assumes everyone else is hiding too."))
S.append(hb("The cloak", "Spell-Storing Item: Invisibility, ten uses",
 "An action, and concentration. Attacks against him have Disadvantage and his next has Advantage, and it ends when he fires or casts. The cannons and the Digi-Jacks aren't him and don't open it. The Mind Sharpener holds it through four failed concentration saves."))
S.append(hb("The shield and the surveyor", "Shield, nine slots' worth · an Eldritch Cannon as Protector",
 "The game's shield is one big bar that doesn't come back by itself; a surveyor comes out and refills it until it's shot down. Here the bar is temporary hit points, 2d8+5 at a time, from a cannon that can do it again every turn, and Shield is the flicker when something gets through."))
S.append(hb("The turrets", "Eldritch Cannon, Explosive Cannon, Fortified Position",
 "Two at once from level 15, both on one Bonus Action, AC 18 and 100 HP each. Standing within 10 ft of one is Half Cover, which is most of his Armor Class. Either can be detonated as a Reaction: 3d8 force to everything within 20 ft, Dex save for half. He hasn't yet been that desperate."))
S.append(hb("Getting up", "Soul of Artifice: Cheat Death",
 "The class capstone, not a canon feat: the games kill him once. It's read here as the shield going down a layer at a time. Each time he'd drop he loses one of the six things he built, the storage deck first and the laser last, and by the end he's a man in a waistcoat at AC 13 with a bare +11."))

S.append(P("Build, level by level", h2)); S.append(rule())
S.append(P("Standard array 10 / 12 / 13 / 15 / 8 / 14 (Str, Dex, Con, Int, Wis, Cha). Merchant: +2 Int, +1 Con, Animal Handling and Persuasion, navigator's tools, Lucky. Human: Alert, and Deception as the extra skill. Levels 3 to 12 are the Pre-Sequel; 13 to 15 the years between the games; 16 to 20 <i>Borderlands 2</i>.", small))
rows = [("1","John","Spellcasting (Fire Bolt, Message), Tinker's Magic; Lucky, Alert","A low-level programmer at Hyperion. <i>Borderlands 2</i> supplies the childhood in one side mission: a grandmother, and the buzz-axe she kept for him"),
 ("2","Angel","Replicate Magic Item: a Bag of Holding, a Wand of the War Mage +1","His daughter is a Siren who can talk to any machine there is. He wires her into Hyperion's satellites. She is the Guardian Angel who walks four Vault Hunters to the first Vault for him, and he takes the credit"),
 ("3","Helios","Artillerist: Shield, Eldritch Cannon; Expendable Assets, one Digi-Jack","The Pre-Sequel opens. The Lost Legion takes Hyperion's moon base and a programmer with a pistol hires six Vault Hunters to take it back"),
 ("4","Elpis","+2 Int (19)","Shot at the moon in a cargo container. Concordia"),
 ("5","The Meriff","Arcane Firearm; Scorching Ray, Invisibility","An old colleague sells him out. Jack spares him and turns to go; the Meriff draws on his back, and dies for it. He says afterwards that he won't make that mistake again, and doesn't"),
 ("6","Felicity","Magic Item Tinker; a Mind Sharpener","He needs a mind to run a robot factory, and the only one to hand is a ship's AI who says no. He installs her anyway and has the Vault Hunters kill what she becomes"),
 ("7","Helios again","Flash of Genius","The station retaken with an army he had built in a week"),
 ("8","The ECHOnet","Telepathic (Int 20)","From here on he's a voice in everyone's ear"),
 ("9","The airlock","Explosive Cannon; Fireball","One of the station's scientists might be a spy. All of them go out of the airlock"),
 ("10","The Eye","Magic Item Adept; a Cloak of Protection, and the wand is +2","The Eye of Helios: the station's laser, built around the eye of the thing from the first Vault. Moxxi, Roland and Lilith help him retake it, and then wreck it under him"),
 ("11","Zarpedon","Spell-Storing Item: the cloak; two Digi-Jacks","The Lost Legion's colonel dead, and the Vault of the Sentinel open"),
 ("12","The Vault","+2 Cha (16)","He touches what's inside and sees the Warrior. Lilith arrives through the air and puts the artifact into his face with her fist. The Vault's mark is burned across it for good"),
 ("13","The mask","Ice Storm, Wall of Fire; Otiluke's Resilient Sphere","His own face, clasped on. Harold Tassiter, Hyperion's chief executive, strangled in his own office"),
 ("14","Handsome Jack","Advanced Artifice; Bracers of Defense","President of Hyperion. The name on everything"),
 ("15","Opportunity","Fortified Position: two cannons","A city with his statue on every corner and men with his face on the streets. A pony made of diamonds, named Butt Stallion"),
 ("16","The train","+2 Cha (18)","<i>Borderlands 2</i> opens. He invites a trainload of Vault Hunters to Pandora and blows up the train"),
 ("17","Bloodwing","Cone of Cold, Wall of Force","The Wildlife Exploitation Preserve. Sanctuary's shields brought down from inside, by a power core he let them win"),
 ("18","Angel","Magic Item Master; a Ring of Protection","She asks the Vault Hunters to kill her, and they do, with him on the ECHO the whole way down"),
 ("19","Roland","Boon of Fate (Int 21)","He appears behind the leader of the Crimson Raiders and shoots him in mid-sentence, and puts a collar on Lilith to charge the Vault Key"),
 ("20","The Warrior","Soul of Artifice","Hero's Pass, the Vault of the Warrior. The headline block")]
S.append(grid([[P("Lvl", cellhead), P("When", cellhead), P("What you get", cellhead), P("Where in the story", cellhead)]] + [[P(a, cellb), P(b, cell), P(c, cell), P(d_, cell)] for a, b, c, d_ in rows], [0.4*inch, 0.95*inch, 2.15*inch, W-3.5*inch]))

S.append(PageBreak()); S.append(P("Snapshots by chapter, with the feats checked", h2)); S.append(rule())
S.append(P("The checks say what each stretch of the story asks of him and whether the level can do it. Most of what he's known for was done by giving an order, and an order isn't a class feature.", small))
def snap(name, where, lvl, lines, checked):
    content = [P(name, snapname), P(where + "  ·  " + lvl, stattag)] + [P(l, snapline) for l in lines] + [P("<b>The feat, checked.</b> " + checked, snapline)]
    t = Table([[content]], colWidths=[W]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("LINEBEFORE",(0,0),(0,-1),2.5,GREEN),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),10),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
    return KeepTogether([t, Spacer(1,7)])
S.append(snap("John, from programming", "Helios and Elpis, the first half of the Pre-Sequel", "Levels 3–6", ["Int 17, then 19 · <b>AC</b> 11, 16 with Shield · <b>HP</b> 24 → 45 · one cannon (2d8, 15 → 30 HP) · one Digi-Jack · Fire Bolt 1d10, then 2d10 + 1d8"], "The game's first hour is a man in a waistcoat with a pistol getting six mercenaries into a cargo container and firing it at the moon. Nothing in it needs more than this: he stays behind a turret and the people he's paying do the fighting. The Meriff is the one time it comes down to him, and it's a single shot at a clerk. What the level can't do is what he does next. A robot army in a week is a factory and a mind he had no right to, and the sheet gives him the idea (Intelligence 19) and none of the output."))
S.append(snap("The hero of Helios", "The second half of the Pre-Sequel, to the Vault of the Sentinel", "Levels 7–12", ["Int 20 · <b>AC</b> 12 with the coat, 17 with Shield · <b>HP</b> 52 → 87 · Flash of Genius · Fireball · the cloak from 11, with two Digi-Jacks"], "He's present for the whole campaign and fights none of its bosses; the Vault Hunters kill Zarpedon and the Sentinel, and he walks in after. Level 11 covers being there: two decoys, Shield, a cannon handing out temporary hit points, and a cloak for when it goes badly. The airlock isn't a feat, it's a door control. Lilith's punch is: it lands on a man with a Siren coming out of thin air at arm's length, which is surprise and no Reaction, and at 87 hit points it doesn't kill him. It does what the story says and marks him."))
S.append(snap("Mr. President", "Between the games, and Borderlands 2 as far as the Control Core", "Levels 13–19", ["Cha 18, Int 21 · <b>AC</b> 14 → 15, 17 by a cannon · <b>HP</b> 94 → 136 · two cannons from 15 · the bracers, the ring"], "Tassiter is a strangling: a grapple on an old man in a chair, and Strength 10 is enough. Roland is one pistol shot. In 5e a pistol does 1d10 and the leader of the Crimson Raiders has a hundred hit points and more, so the rules don't do it and the sheet doesn't claim they do: it's a cutscene, and a cutscene is a story beat, not a damage roll. What the rules do cover is how he got there, unseen and behind him, which is the cloak. The collar on Lilith is the same kind of thing, a made item and a moment when she was looking at someone else."))
S.append(snap("The Vault of the Warrior", "Hero's Pass, the end of Borderlands 2", "Level 20", ["The headline block: AC 17 beside a cannon, 143 HP under a shield, the laser, two cannons, two Digi-Jacks, six things to give up"], "The fight as the game runs it: copies of him, a shield, a surveyor that refills it, turrets, a cloak, the laser. All of it is on the sheet and all of it is his own. The walkthroughs call him one of the easier bosses in the game, and the real fight is the Warrior he wakes up afterwards. The arena agrees. On these sheets he wins about three fights in ten. He beats whoever can't get to a man behind two holograms and a line of fire: Talion, Spike and Goblin Slayer every time, Kyle Crane three times in five. He's a little under even with Dark Link, takes Arthur Morgan and Musashi one time in three, Itachi one in four and Battle Beast one in five. Guts gets to him forty-nine times in fifty. The Slayer, Link, Anderson, Might Guy, Adam Smasher, Jin Sakai, V and Kratos have never lost to him, and most of them are through all six of his second chances by the third round."))

S.append(KeepTogether([P("A DM's dial", h2), rule(), P("<b>Down.</b> Expendable Assets is the homebrew and the strongest thing here. One Digi-Jack instead of two, or none coming back, and he's the boss the walkthroughs describe with a little less patience required. Soul of Artifice, as run, is six separate returns at 20; a stricter table makes him burn all six items at once for 120, the same total and one use. <b>Up, and still on the sheet.</b> Otiluke's Resilient Sphere on himself with the cannons outside it is the game's undamageable shield: nothing gets in, he can't fire out, and the cannons and the Digi-Jacks carry on until his concentration goes. It's legal and it isn't run in the arena, where it would only be a stall. Summon Construct on a 4th- or 5th-level slot is a Loader. <b>Up, and off it.</b> Hyperion: WAR Loaders by moonshot as a lair action, the Eye of Helios, a city of men with his face, the AI that Nakayama made of him (<i>Tales from the Borderlands</i>), and the Warrior, which is a stat block of its own. Timothy Lawrence, the double who is the Pre-Sequel's Doppelganger and is still alive in <i>Borderlands 3</i>, would be this sheet at about level 11 with a conscience. <b>Left alone:</b> Strength 10, Wisdom 8, 143 hit points.")]))
doc.build(S, onFirstPage=on_page, onLaterPages=on_page); print("ok")
